import { defineStore } from 'pinia';
import { ref, computed } from 'vue';
import type { User } from '../types/app';
import { useRoute } from 'vue-router';
import { getMeasureList } from '@/api/system';

export const useUserStore = defineStore({
    id: 'user',
    state() {
        return {
            userInfo: null as User | null,
        };
    },
    actions: {
        getUserInfo(userInfo: User) {
            this.userInfo = userInfo;
        },

    },

    // 添加如下配置
    persist: {
        enabled: true,
        strategies: [
            {
                key: 'userInfo',
                storage: localStorage,
                paths: ['userInfo']
            }
        ]
    }
});


export const useSettingStore = defineStore('systemSetting', () => {
    const route = useRoute();
    const isCollapse = ref<boolean>(false);
    const mapCenter = [104.832038, 28.744];
    const factroyName = '宜宾三江新区长江工业园';
    const measureList = ref([]);
    const setCollapse = () => {
        isCollapse.value = !isCollapse.value;
    };
    const getMeasureListHandler = async (params: any) => {
        if (!params.bizModule) {
            return;
        }
        measureList.value = await getMeasureList(params);
    };

    const currentApp = computed(() => []);

    return {
        factroyName,
        isCollapse,
        setCollapse,
        mapCenter,
        currentApp,
        getMeasureListHandler,
        measureList
    };
});

export const useMenuStore = defineStore('menuStore', () => {
    const menuList = ref([]);
    const buttonList = ref([]);
    const bizModule = ref(1);
    const setMenu = (res: any) => {
        menuList.value = res;
    };
    const setButtonList = (res: any) => {
        buttonList.value = res;
    };
    return {
        menuList,
        buttonList,
        bizModule,
        setMenu,
        setButtonList
    };
}, {
    persist: {
        enabled: true,
        strategies: [
            {
                key: 'menuList',
                storage: localStorage,
                paths: ['menuList']
            },
            {
                key: 'buttonList',
                storage: localStorage,
                paths: ['buttonList']
            },
            {
                key: 'bizModule',
                storage: localStorage,
                paths: ['bizModule']
            }
        ]
    }
});